// ─── HTML Interview Questions (200) ─────────────────────────────────────
export const HTML_QUESTIONS = [
  // ── Easy ─────────────────────────────────────────────────────────────────
  ["What is HTML and what does it stand for?", "easy", "HTML stands for HyperText Markup Language. It's the standard language for creating web pages and web applications. HTML describes the structure and content of a page using elements (tags) like headings, paragraphs, links, images, and forms. Browsers parse HTML to render visible content. HTML is not a programming language — it's a markup language that annotates text for display."],
  ["What is the difference between HTML elements and HTML attributes?", "easy", "Elements are the building blocks (e.g., <p>, <div>, <img>). Attributes provide additional configuration on elements (e.g., class='name', id='main', src='image.jpg', href='url'). Attributes go in the opening tag. Some elements require specific attributes (img needs src); others have optional attributes. Elements can have multiple attributes."],
  ["What is the <!DOCTYPE html> declaration and why is it needed?", "easy", "<!DOCTYPE html> tells the browser to render the page in standards mode (not quirks mode). Without it, the browser assumes older HTML versions and uses quirks mode — inconsistent box model, different CSS rendering, bugs. HTML5 uses the simple <!DOCTYPE html> (case-insensitive). It must be the very first line in the HTML document, before <html>."],
  ["What is the difference between <head> and <body>?", "easy", "<head> contains metadata about the document: title, meta tags, link/script references, styles. Content in <head> is not directly visible on the page. <body> contains the visible content: text, images, forms, interactive elements. The browser renders <body> content. Only <body> content appears in the viewport."],
  ["What are semantic HTML elements? Name five examples.", "easy", "Semantic elements clearly describe their meaning in human and machine-readable ways. Examples: <header> (page/section header), <nav> (navigation links), <main> (primary content), <article> (self-contained content), <section> (thematic grouping), <aside> (tangential content), <footer> (page/section footer), <figure> (illustrations/diagrams). Semantic elements improve accessibility (screen readers), SEO (search engines), and code readability."],
  ["What is the difference between <div> and <span>?", "easy", "<div> is a block-level container (takes full width, starts new line). <span> is an inline container (only takes content width, no line breaks). Use <div> for layout sections, grouping block elements. Use <span> for inline text styling, highlighting parts of text. Both are non-semantic — prefer semantic elements where possible."],
  ["What are block-level vs inline elements? Give examples of each.", "easy", "Block-level: take full width, start new line, respect all CSS properties. Examples: <div>, <p>, <h1>-<h6>, <ul>, <ol>, <li>, <header>, <footer>, <section>, <article>. Inline: flow within text, only take content width, ignore width/height/top-bottom margins. Examples: <span>, <a>, <strong>, <em>, <img> (inline-block), <label>, <input>, <button>."],
  ["What is the purpose of the alt attribute on <img>?", "easy", "alt provides alternative text for images. Critical for accessibility: screen readers read alt text to visually impaired users. Also displayed when image fails to load. SEO benefit — search engines index alt text. Must be descriptive: alt='Red sunset over mountains' not alt='image'. Decorative images should have alt='' (empty) to tell screen readers to skip them."],
  ["What is the difference between <strong> and <b>?", "easy", "<strong> indicates semantic importance (strong emphasis) — affects screen reader tone/inflection. <b> is presentational only (bold styling) with no added meaning. In HTML5, <strong> implies importance, seriousness, or urgency. <b> is for stylistic offset (keywords, product names). Use <strong> when the content is important; <b> when only visual bold is needed. Same for <em> (emphasis) vs <i> (italic styling)."],
  ["What is the difference between <em> and <i>?", "easy", "<em> indicates stressed emphasis — changes meaning of the sentence (like verbal emphasis). Screen readers change vocal emphasis. <i> is presentational italic (technical terms, foreign words, thoughts) with no semantic weight. Example: 'I <em>really</em> need this' vs 'The word <i>bon appétit</i> is French'. Use <em> for meaning change; <i> for stylistic conventions."],
  ["What are the different input types in HTML5?", "easy", "HTML5 input types: text (default), password, email, number, tel, url, search, date, datetime-local, month, week, time, color, range, file, checkbox, radio, submit, reset, button, hidden. Each provides browser-specific UI (date picker, color picker, number stepper) and validation. Mobile browsers show appropriate keyboards (numeric for tel, @ for email)."],
  ["What is the difference between <ul>, <ol>, and <dl>?", "easy", "<ul> (unordered list): bullet points, order doesn't matter. <ol> (ordered list): numbered/lettered, order matters. <dl> (description list): term-description pairs (<dt> + <dd>). Use <ul> for navigation, features lists, etc. Use <ol> for step-by-step instructions, rankings. Use <dl> for glossaries, metadata pairs (key-value)."],
  ["What does the href attribute do on an anchor tag?", "easy", "href specifies the URL the link navigates to. Values: absolute URL (https://example.com), relative URL (/about or about.html), fragment (#section), mailto (mailto:email@example.com), tel (tel:+1234567890), javascript: (avoid, security risk). Without href, <a> is not keyboard accessible (can't tab to it). Use href='#' for placeholder links, or omit href and add role='button' for button-like anchors."],
  ["What is the target='_blank' attribute and what security risk does it carry?", "easy", "target='_blank' opens the link in a new tab/window. Security risk: the new page can access the opener via window.opener (tabnabbing — phishing attack). Fix: add rel='noopener noreferrer'. rel='noopener' prevents the new page from accessing window.opener. rel='noreferrer' also hides referrer info. Modern browsers treat target='_blank' as noopener by default, but always add it for safety."],
  ["What is an HTML comment and how do you write one?", "easy", "HTML comments: <!-- comment text -->. Comments are not rendered by the browser. Used for: documenting code, disabling sections temporarily, marking to-do items. Comments can span multiple lines. Don't nest comments (<!-- <!-- --> --> breaks). Comments inside <script> or <style> use their respective comment syntax (//, /* */)."],
  ["What is the difference between <script> placed in <head> vs end of <body>?", "easy", "Scripts in <head> block HTML parsing — the browser stops rendering until the script downloads and executes. Can delay page load significantly. Scripts at end of <body> run after all HTML is parsed — no rendering delay, DOM is ready. Modern practice: use async or defer in <head> instead of end-of-body placement. async: download without blocking, execute when ready. defer: download without blocking, execute after parsing."],
  ["What is the difference between absolute and relative URLs?", "easy", "Absolute URL: full URL with protocol and domain (https://example.com/images/photo.jpg). Works from any context. Relative URL: path relative to current page (images/photo.jpg) or root-relative (/images/photo.jpg). Lighter, portable (works in dev, staging, prod). Root-relative starts with / (from domain root); document-relative starts with the current path. Prefer relative URLs within your own site for portability."],
  ["What are void elements in HTML? Give examples.", "easy", "Void (self-closing) elements have no content and don't need closing tags. Examples: <br> (line break), <hr> (thematic break), <img> (image), <input> (form input), <meta> (metadata), <link> (external resources), <area> (image map area), <base>, <col>, <embed>, <source>, <track>, <wbr>. In HTML5, don't use trailing slash (<br /> is valid but unnecessary). They can't have children."],
  ["What is the purpose of the <label> element in forms?", "easy", "<label> associates text with a form input. Two ways: 1) wrap the input: <label>Name: <input name='name'></label>. 2) use for attribute: <label for='email'>Email:</label> <input id='email' name='email'>. Clicking the label focuses the input. Essential for accessibility (screen readers announce label) and usability (larger click target). Always label form controls."],
  ["What is the difference between id and class attributes?", "easy", "id: unique identifier — used once per page. Used for: anchor links (#section), JavaScript targeting (getElementById), CSS with # selector. class: reusable identifier — used multiple times. Used for: CSS styling with . selector, JavaScript targeting (getElementsByClassName). An element can have multiple classes (class='btn primary large'). An element can have only one id. ids have higher CSS specificity than classes."],
  ["What is an HTML entity? Give three examples.", "easy", "HTML entities represent special characters that would otherwise be interpreted as HTML code. Format: &name; or &#number;. Examples: &lt; (<), &gt; (>), &amp; (&), &quot; (\"), &apos; ('), &nbsp; (non-breaking space), &copy; (©), &reg; (®), &#9829; (♥). Use entities to display reserved HTML characters safely."],
  ["What does the placeholder attribute do on an input?", "easy", "placeholder shows hint text inside an input when it's empty. Disappears when user starts typing. Not a replacement for <label> — placeholder text often has low contrast and disappears, making it inaccessible. Use placeholder for examples ('e.g., jane@example.com'), not critical info. Always pair with a persistent <label>."],
  ["What is the required attribute in HTML forms?", "easy", "required makes an input mandatory — the browser won't submit the form if the field is empty. Built-in validation: shows browser-defined error message (customizable with setCustomValidity). Works on: text, email, url, number, tel, password, checkbox, file, date inputs and <select>. Combine with pattern for format validation. Note: server-side validation is still needed (client-side can be bypassed)."],
  ["What is the difference between <article>, <section>, and <div>?", "easy", "<article>: self-contained, independently distributable content (blog post, news story, comment). <section>: thematic grouping of content, should have a heading. <div>: generic container with no semantic meaning. Use <article> when content could be syndicated (RSS). Use <section> for chapters, tab panels, grouped form fields. Use <div> only when no semantic element fits (last resort)."],
  ["What is the <nav> element used for?", "easy", "<nav> represents a section with navigation links (site menus, table of contents, breadcrumbs). Major navigation blocks should use <nav>. The main site navigation should be the primary <nav>. Not all links need <nav> — only blocks of navigational links. Multiple <nav> elements per page are fine (primary navigation, footer links, pagination). Helps screen reader users find and skip to navigation."],
  ["What is the <main> element?", "easy", "<main> represents the primary content of a page. There should be only ONE <main> element per page (don't include repeated content like sidebars, navigation, logos). <main> should NOT be a child of <article>, <aside>, <footer>, <header>, or <nav>. Provides a landmark for screen readers — users can jump directly to main content. Skip-to-content links typically target <main>."],
  ["What is the <footer> and <header> element?", "easy", "<header> represents introductory content or navigational aids: logo, site title, search bar, navigation. Can be used inside articles/sections for their headers. Multiple <header>s per page are fine. <footer> represents closing content: copyright, contact info, related links, sitemap. Same — multiple allowed per page (page footer, article footer). Both have landmark roles for accessibility."],
  ["What does the disabled attribute do on a form element?", "easy", "disabled prevents user interaction with the element. The element: can't be focused, can't be clicked (for buttons), not submitted with form, appears grayed (by default), skipped in tab order. Input-related: no validation for disabled fields. To make an element non-interactive but submitted/styled normally: use readonly (for text inputs) instead of disabled. disabled value is irrelevant — presence alone disables."],
  ["What is the <br> tag and when should you avoid it?", "easy", "<br> inserts a line break within text. Appropriate: poems, addresses, code examples where line breaks are semantic. Avoid: creating spacing between blocks (use CSS margin/padding), separating form fields, building layout (use CSS). Multiple <br> in a row is always wrong — use margin instead. <br> is a void element (no closing tag)."],
  ["What is the <hr> element?", "easy", "<hr> (horizontal rule) represents a thematic break between content sections — a story shift, a scene change. Not just a horizontal line — it's semantic. Browsers render it as a line by default, but CSS can restyle it. Use where a new section begins in related content. Don't use <hr> purely for decoration — use CSS borders instead."],

  // ── Medium ────────────────────────────────────────────────────────────────
  ["What is the DOM (Document Object Model)?", "med", "DOM is a tree-like representation of an HTML document that JavaScript can interact with. The browser parses HTML into a tree of Node objects (elements, attributes, text). JS can query, traverse, and manipulate the DOM: document.querySelector, element.textContent, element.addEventListener. The DOM is live — changes reflect immediately in the rendered page. Not the same as HTML source (the DOM can be modified)."],
  ["What is the difference between innerHTML, textContent, and innerText?", "med", "innerHTML: returns/sets HTML content (parsed as HTML). Security risk with user input (XSS). textContent: returns ALL text content (including hidden elements), ignores CSS styling, faster. innerText: returns VISIBLE text only (respects CSS display: none), approximates rendered text layout. Use textContent for reading/writing plain text (safe, performant). Use innerHTML only when you need HTML rendering with sanitized input."],
  ["What is the difference between <script>, <script async>, and <script defer>?", "med", "Default <script>: blocks HTML parsing — downloads and executes immediately (render-blocking). <script async>: downloads in parallel (non-blocking), executes as soon as downloaded (order not guaranteed). <script defer>: downloads in parallel, executes AFTER HTML parsing completes (in document order). Use defer for scripts that rely on DOM (analytics, DOM manipulation). Use async for independent scripts (counters, ads)."],
  ["What are data-* attributes and when would you use them?", "med", "data-* attributes store custom data on HTML elements: <div data-user-id='123' data-role='admin'>. Access via JS: element.dataset.userId (camelCase). Use for: storing state, configuration tied to a DOM element, JS-driven UI behavior, testing hooks. Don't use for: storing sensitive data (visible in HTML), large datasets (use JS variables). data-* is accessible via CSS attribute selectors ([data-active='true'])."],
  ["What is the difference between GET and POST form methods?", "med", "GET: appends form data to URL as query string (?name=value). Visible in browser history, bookmarkable, cached. Limited data length (~2000 chars). Default method. Use for: search forms, read-only operations, idempotent requests. POST: sends data in request body (not in URL). No length limit, not cached, not bookmarkable. Use for: creating/updating data, file uploads, sensitive data (passwords)."],
  ["What is the enctype attribute on a <form> and when do you use multipart/form-data?", "med", "enctype specifies how form data is encoded before sending. application/x-www-form-urlencoded (default): space → +, special chars encoded. multipart/form-data: no encoding, required for file uploads (<input type='file'>). text/plain: only spaces encoded (rarely used). If enctype is wrong for file uploads, the file won't be sent properly. Always use method='POST' with enctype='multipart/form-data' for file uploads."],
  ["What is the <template> element in HTML5?", "med", "<template> holds HTML fragments that are not rendered until cloned via JavaScript. The content is parsed but inert (images don't load, scripts don't run, styles don't apply). Access via: template.content (DocumentFragment). Clone: document.importNode(template.content, true). Used for: client-side templating, repeating UI patterns, Web Components, dynamic content insertion. More efficient than innerHTML — content is pre-parsed."],
  ["What is the <slot> element and how is it used in Web Components?", "med", "<slot> is a placeholder in a Web Component's Shadow DOM that projects light DOM content into the component. Named slots: <slot name='header'> allows <span slot='header'> from light DOM. Default slot: <slot> (unnamed) catches all children without a slot attribute. Multiple slots can be used. Slots enable content projection — the component defines structure, the user provides content. Fallback content in <slot> renders if no content provided."],
  ["What is the difference between <iframe> and <embed>?", "med", "<iframe> embeds another HTML document within the current page — full document with own browsing context, JS, CSS. Sandboxable (security). Most common embed method. <embed> embeds external resources (PDF, Flash, plugins) using a browser plugin. Less secure, no sandbox, outdated for most use cases. Use <iframe> for: third-party content (YouTube, maps), sandboxed widgets, micro-frontends. Use <video>/<audio> for media instead of <embed>."],
  ["What are ARIA roles and attributes? Why do they matter?", "med", "ARIA (Accessible Rich Internet Applications) provides additional semantics for assistive technologies. Roles: role='button', role='navigation', role='dialog'. Attributes: aria-label, aria-hidden, aria-expanded, aria-live, aria-describedby. WAI-ARIA matters when native HTML semantics are insufficient (custom controls, dynamic content). First rule of ARIA: don't use it if native HTML works (use <button> not role='button' on <div>)."],
  ["What is the tabindex attribute and how does it affect keyboard navigation?", "med", "tabindex controls element focusability and tab order. tabindex='0': element is focusable (by Tab), in natural tab order (DOM order). tabindex='-1': element is programmatically focusable (element.focus()), but NOT in tab order. tabindex='5' (positive): element becomes focusable, placed BEFORE natural order (all positive tabindex elements ordered by value, then natural order). Avoid positive tabindex values — they create confusing navigation flow. Use DOM order instead."],
  ["What is the difference between <button type='submit'> and <input type='submit'>?", "med", "Both submit the form. <button> can contain HTML content (icons, bold text, images). <input> is a void element — can only show text via value attribute. <button type='submit'> is preferred: styling flexibility, HTML content, pseudo-elements (::before/::after). <button> without type defaults to type='submit' inside a form (type='button' for non-submit). <button> also supports type='reset' and type='button'."],
  ["What is the <picture> element and how does it enable responsive images?", "med", "<picture> provides multiple image sources for different viewports/resolutions. Contains one or more <source> elements (with media/type/srcset attributes) and a fallback <img>. Example: <picture> <source media='(min-width: 800px)' srcset='large.jpg'> <source media='(min-width: 400px)' srcset='medium.jpg'> <img src='small.jpg' alt='...'> </picture>. Enables: art direction (different crops per breakpoint), format selection (WebP fallback with type attribute), resolution switching."],
  ["What is the srcset attribute on <img>?", "med", "srcset provides multiple image candidates for the browser to choose based on viewport width and device pixel ratio. Syntax: srcset='image-320.jpg 320w, image-640.jpg 640w, image-960.jpg 960w' (w = width descriptor). Combine with sizes: sizes='(max-width: 600px) 100vw, 50vw'. The browser picks the best image based on viewport width, DPR, and bandwidth. Compared to <picture>, srcset is simpler for resolution switching (same image, different sizes)."],
  ["What is lazy loading of images and how do you implement it natively?", "med", "Lazy loading defers offscreen image loading until the user scrolls near them. Native: <img loading='lazy' src='...'>. loading='lazy' (load when near viewport), loading='eager' (load immediately, default), loading='auto' (browser decides). Benefits: saves bandwidth, faster initial page load. Works for <img> and <iframe>. For background images: use Intersection Observer API. Set explicit width/height to prevent layout shift when images load later."],
  ["What is the <details> and <summary> element?", "med", "<details> creates a native collapsible/expandable widget. <summary> is its visible heading. <details> <summary>More Info</summary>Hidden content revealed on click.</details>. The open attribute controls default state: <details open>. Fully accessible by default (keyboard, screen reader). Browser renders as a native disclosure widget. CSS can customize: details[open] { ... }, summary { cursor: pointer; }. No JS needed for basic disclosure widgets."],
  ["What is the <dialog> element in HTML5?", "med", "<dialog> creates a native modal/non-modal dialog. Show: dialog.showModal() (modal — blocks interaction with rest of page), dialog.show() (non-modal). Close: dialog.close(). CSS ::backdrop pseudo-element styles the overlay background. Accessibility: focus is trapped inside, Escape closes by default, role='dialog' implicitly. Closing without JS: <form method='dialog'> <button>Close</button> </form>. Native dialog replaces custom modal implementations."],
  ["What is the contenteditable attribute?", "med", "contenteditable='true' makes an element editable by the user (like a rich text editor). <div contenteditable='true'>Edit me</div>. Supports: bold/italic (Ctrl+B/I), lists, line breaks. Use with JS: document.execCommand (deprecated) or document.queryCommandState. Modern: use Input Events (input, beforeinput) with Range API for undo support. Be careful with XSS — sanitize output. contenteditable is not a form control — its content isn't submitted with forms."],
  ["What is the difference between <link rel='stylesheet'> and @import in CSS?", "med", "<link> in HTML loads CSS in parallel (blocking). @import inside CSS loads sequentially (file must download before @import resolves). @import causes cascade blocking — files load one after another. <link> is preferred: faster (parallel download), no FOUC risk, simpler. @import is rarely used now — mainly for splitting CSS within a file. @import also doesn't work in media queries (on <link>)."],
  ["What is the meta viewport tag and why is it important for responsive design?", "med", "<meta name='viewport' content='width=device-width, initial-scale=1.0'> tells mobile browsers to render at device width (not a simulated desktop 980px). Without it, mobile browsers zoom out to show the full page. width=device-width matches device screen width. initial-scale=1 sets 1:1 zoom ratio. Essential for responsive designs. Additional: maximum-scale=1 (disables pinch zoom — use with caution, accessibility concern), user-scalable=no."],
  ["What are Open Graph meta tags and why are they used?", "med", "Open Graph (OG) meta tags control how content appears when shared on social media (Facebook, Twitter, LinkedIn, Discord). Tags: og:title, og:description, og:image, og:url, og:type (website, article, etc.), og:site_name. Example: <meta property='og:title' content='My Article'>. Twitter uses similar: twitter:card, twitter:image. Proper OG tags ensure link previews show the correct title, description, and image. Essential for social media sharing."],
  ["What is the <meta charset='UTF-8'> tag for?", "med", "<meta charset='UTF-8'> sets the character encoding to UTF-8 (Unicode). UTF-8 supports all characters from all languages (emoji, accents, CJK, special symbols). Should be the first <meta> tag in <head>. Without it, the browser may misinterpret characters (mojibake). The charset meta tag is only honored if it's within the first 1024 bytes of the document (place early)."],
  ["How does the browser render an HTML page (critical rendering path)?", "med", "1) HTML parsing: bytes → tokens → nodes → DOM tree. 2) CSS parsing: CSS bytes → CSSOM. 3) Render Tree: combine DOM + CSSOM (only visible elements). 4) Layout: calculate element geometry (position, size). 5) Paint: fill pixels (colors, images, shadows). 6) Composite: layer composition (GPU). The browser starts rendering as soon as it has content — doesn't wait for whole page. JavaScript blocks HTML parsing (unless async/defer). CSS blocks rendering until CSSOM is built."],
  ["What is reflow vs repaint in the browser?", "med", "Reflow (layout): recalculates element positions and sizes when geometry changes (width, height, font-size, DOM addition/removal). Expensive — affects entire document or subtree. Repaint: fills pixels when visual properties change without layout (color, background, visibility). Less expensive than reflow. Changing layout properties triggers both reflow + repaint. Changing paint-only properties triggers only repaint. Changing transform/opacity triggers only composite (GPU, cheapest)."],
  ["What is the difference between <th> and <td> in HTML tables?", "med", "<th> (table header) defines a header cell — bold, centered by default. Must use scope attribute: scope='col' (header for column), scope='row' (header for row). <td> (table data) defines a standard cell. <th> is critical for accessibility — screen readers use scope to associate headers with cells. Always use <thead>, <tbody>, <tfoot> for proper table structure. Complex tables: use headers attribute matching cell id for multiple header associations."],
  ["What are the accessibility best practices for HTML forms?", "med", "1) Every input needs a <label> (explicitly associated via for/id or wrapped). 2) Group related fields with <fieldset> and <legend>. 3) Use appropriate input types (email, tel, number). 4) Provide clear error messages with aria-describedby. 5) Use required, pattern, min/max for built-in validation. 6) Ensure error messages are announced: aria-live='polite' or role='alert'. 7) Don't disable form validation (novalidate) without accessible alternatives. 8) Keyboard-navigable tab order."],
  ["What is the difference between <link> and <a> tags?", "med", "<link> is a void element in <head> that links external resources (CSS, favicon, preload, canonical). Not clickable. <a> (anchor) is an inline element in <body> that creates clickable hypertext links. <link> is metadata; <a> is interactive content. Both have href attribute but serve different purposes. <link> also supports rel: stylesheet, preload, prefetch, icon, canonical, alternate."],
  ["What is the download attribute on an anchor tag?", "med", "download on <a> forces file download instead of navigation. <a href='file.pdf' download='report.pdf'>Download Report</a>. The optional value sets the suggested filename. Works for same-origin URLs and blob URLs. For cross-origin: requires CORS. Without download, clicking the link navigates to the file (or opens in browser if supported). download is useful for: generated files (blob URLs), PDFs you want downloaded not viewed, saving server files."],
  ["What is the <base> element in HTML?", "med", "<base> sets the base URL for all relative URLs in the document. <base href='https://example.com/'>. All relative links (<a href='about'>) resolve against base. Only one <base> per document, must be in <head>. Can also set target: <base target='_blank'> — all links open in new tab. Caution: base URL affects all relative paths (scripts, styles, images). If base or target doesn't work as expected, check <base> usage."],
  ["What is the difference between HTML4 and HTML5?", "med", "HTML5 introduced: semantic elements (header, nav, main, article, section, footer), new input types (email, date, tel, number, color, range, url, search), form validation (required, pattern, min, max), multimedia (video, audio, canvas, SVG), APIs (Geolocation, Drag and Drop, Web Storage, Web Workers, History API), DOCTYPE simplified (<!DOCTYPE html>), deprecated presentational elements (font, center, strike), async/defer for scripts, contenteditable, data-* attributes."],
  ["What are Web Components and what are their four parts?", "med", "Web Components are reusable custom elements with encapsulated styling and behavior. Four parts: 1) Custom Elements: define new HTML tags via class extends HTMLElement. 2) Shadow DOM: encapsulated DOM and styles (scoped CSS, no inheritance). 3) HTML Templates: <template> for reusable markup. 4) HTML Imports (deprecated — use ES modules). Web Components are framework-agnostic — work in any project. Used by: YouTube, GitHub, Google Maps."],
  ["What is the Shadow DOM?", "med", "Shadow DOM provides DOM and style encapsulation. A shadow root (attached to an element) creates a separate DOM subtree that's hidden from the main document. Styles inside shadow DOM don't leak out; global styles don't leak in (unless using CSS custom properties or ::part). Types: open (accessible via element.shadowRoot) and closed (element.shadowRoot = null). Shadow DOM is essential for Web Components — it guarantees component isolation."],
  ["What is the difference between Custom Elements and Web Components?", "med", "Custom Elements are a SPECIFIC API — defining new HTML elements via customElements.define(). Web Components is the BROADER term encompassing all four standards: Custom Elements, Shadow DOM, HTML Templates, and (deprecated) HTML Imports. Custom Elements define the TAG; Shadow DOM provides encapsulation; Templates provide markup. You can use Custom Elements without Shadow DOM (light DOM components)."],
  ["What is the preload, prefetch, and preconnect link hints?", "med", "preload: <link rel='preload' href='font.woff2' as='font'> — tells browser to fetch RESOURCE early (high priority, current page). prefetch: <link rel='prefetch' href='next-page.html'> — hints browser to fetch for FUTURE navigation (low priority, idle time). preconnect: <link rel='preconnect' href='https://api.example.com'> — pre-connects to origin (DNS + TCP + TLS). Use preload for critical resources (fonts, LCP images). Use preconnect for third-party origins. Use prefetch for likely next-page resources."],
  ["What is progressive enhancement vs graceful degradation?", "med", "Progressive enhancement: start with a basic, functional experience (HTML-only), then layer on enhancements (CSS, JS) for modern browsers. Graceful degradation: build for modern browsers first, then add fallbacks for older ones. Progressive enhancement is preferred — it's resilient (works even when JS fails, CSS fails to load), accessible (works with assistive tech), and mobile-friendly. Graceful degradation assumes JS availability, which isn't guaranteed."],

  // ── Hard ──────────────────────────────────────────────────────────────────
  ["What is the critical rendering path and how do you optimise it?", "hard", "Critical rendering path: bytes → DOM → CSSOM → Render Tree → Layout → Paint → Composite. Optimizations: 1) Minimize render-blocking resources (inline critical CSS, defer JS), 2) Preload key resources (fonts, LCP images), 3) Reduce CSS size (minify, purge unused), 4) Use server push (HTTP/2), 5) Optimize images (WebP, AVIF, responsive sizes), 6) Minify HTML/CSS/JS, 7) Use CDN, 8) Enable compression (Brotli/Gzip), 9) Reduce redirects, 10) Use HTTP cache headers."],
  ["How does the browser parse HTML and build the DOM?", "hard", "The browser reads HTML byte by byte, converts to characters, tokenizes into start/end tags, attribute names/values, and text content. The tokenizer (state machine) creates tokens. The tree construction algorithm processes tokens to build the DOM tree. When the parser encounters external resources (CSS, JS, images): CSS blocks rendering (CSSOM needed), default <script> blocks parsing (waits for script), async/defer scripts non-blocking. The parser uses speculative parsing for resource discovery (preload scanner)."],
  ["What is CSSOM and how does it combine with DOM to form the Render Tree?", "hard", "CSSOM (CSS Object Model) is a tree of CSS rules matched to elements. Built by: parsing CSS bytes → tokens → rules → cascade resolution → computed values. The Render Tree combines DOM (visible elements only) + CSSOM (computed styles). display: none elements are NOT in the render tree. visibility: hidden IS in the render tree. The render tree is what gets painted — it contains only visible elements with their computed styles. Building the render tree is matching + resolving."],
  ["What is layout thrashing and how do you avoid it?", "hard", "Layout thrashing occurs when JS repeatedly forces synchronous layout reads/writes in rapid succession. Example: for loop reads element.offsetHeight (forces layout), then sets element.style.height (invalidates layout), repeats — forcing layout recalculation each iteration. Avoid: batch DOM reads together (read all measurements first), batch writes together (apply after reads), use requestAnimationFrame for visual changes, use ResizeObserver instead of scroll/resize events. Tools: Chrome DevTools Performance tab shows forced reflow warnings."],
  ["What is the difference between DOMContentLoaded and window.load events?", "hard", "DOMContentLoaded: fires when HTML is fully parsed and DOM tree is built, but external resources (images, stylesheets, iframes) may still be loading. Does NOT wait for async scripts, DOES wait for defer scripts. window.load: fires when ALL resources (images, stylesheets, scripts, iframes, fonts) have finished loading. DOMContentLoaded is earlier (~2-5x faster). Use DOMContentLoaded for attaching event handlers and initializing non-resource-dependent features. Use load for layout-sensitive operations (image dimensions known)."],
  ["What are document fragments and why are they used for performance?", "hard", "A DocumentFragment is a lightweight, in-memory DOM container. Changes to a fragment don't trigger reflow/repaint. When added to the live DOM, the fragment and its children are inserted as one batch (single reflow). Example: const fragment = document.createDocumentFragment(); for (...) { const li = document.createElement('li'); fragment.appendChild(li); } ul.appendChild(fragment);. Much faster than appending each <li> individually (avoids layout thrashing)."],
  ["What is the Intersection Observer API and how is it used?", "hard", "Intersection Observer asynchronously observes when an element enters or leaves the viewport (or a parent element). const observer = new IntersectionObserver((entries) => { entries.forEach(e => { if (e.isIntersecting) { /* lazy load */ } }); }, { threshold: 0.5 }); observer.observe(element). Use cases: lazy loading images/videos, infinite scroll, scroll-based animations, ad visibility tracking, read progress indicators. Much more performant than scroll event handlers."],
  ["What is the MutationObserver API?", "hard", "MutationObserver watches for DOM changes (additions, removals, attribute changes, text changes). const observer = new MutationObserver((mutations) => { mutations.forEach(m => console.log(m.type)); }); observer.observe(target, { childList: true, subtree: true, attributes: true }). Use cases: detecting element injection, tracking DOM changes in third-party widgets, building dev tools (React DevTools), reacting to data-* attribute changes. More performant than DOMSubtreeModified event."],
  ["What is the ResizeObserver API?", "hard", "ResizeObserver watches element size changes (not just window resize). const observer = new ResizeObserver((entries) => { entries.forEach(e => console.log(e.contentRect.width)); }); observer.observe(element). Unlike resize event (window-only), ResizeObserver tracks individual element dimensions. Use cases: responsive components, canvas resize, text overflow detection, container queries polyfill. Useful in complex layouts where elements resize independently of viewport."],
  ["What is the difference between compositing, painting, and layout in browser rendering?", "hard", "Layout: calculates element geometry (width, height, position). Painting: fills pixels for each layer (colors, text, images, borders, shadows). Compositing: combines layers in correct order (z-index, transforms, opacity). Layout changes trigger Paint + Composite. Paint changes trigger Composite only (if element is on its own layer). transform/opacity changes trigger Composite only (GPU, 60fps). Each step is progressively more expensive."],
  ["What is the will-change CSS hint and how does it affect browser rendering?", "hard", "will-change: property-name hints the browser that this property will change soon. The browser can optimize ahead of time (usually by creating a compositor layer). will-change: transform, opacity promotes the element to a GPU layer. Use sparingly — only for known upcoming animations or transitions. Overuse causes excessive memory usage (too many layers). Best: set just before animation starts, unset after. Not recommended for: elements that rarely animate, or as a performance cure-all."],
  ["What is the Canvas API vs SVG? When would you use each?", "hard", "Canvas: pixel-based raster API. Drawing commands (fillRect, arc, drawImage) paint pixels on a grid. Better for: animations, gaming, image processing, pixel manipulation, large particle systems. Doesn't retain element objects (cleared with each frame). SVG: vector-based DOM API. Elements are retained in DOM — can attach events, CSS, and reflow naturally. Better for: static graphics, icons, charts, interactive diagrams, responsive graphics (scales infinitely). Canvas is fast but manual; SVG is slower but interactive."],
  ["What is WebGL and what problem does it solve?", "hard", "WebGL (Web Graphics Library) is a JavaScript API for rendering 2D and 3D graphics using the GPU. Based on OpenGL ES. The <canvas> element provides the rendering surface. WebGL enables: 3D visualizations, games in browser, GPU-accelerated computation (GPGPU via WebGL2), image/video processing, data visualization (3D graphs, molecular models). Not easy to use directly — use libraries like Three.js, Babylon.js, PixiJS."],
  ["What is the Web Animations API (WAAPI)?", "hard", "WAAPI provides a JavaScript API for animations (replaces setTimeout-based animations). element.animate([{ transform: 'translateY(0)' }, { transform: 'translateY(-20px)' }], { duration: 500, iterations: Infinity, easing: 'ease-in-out' }). Returns Animation object with play, pause, reverse, cancel, finish methods. More powerful than CSS animations: dynamic keyframes, play state control, timeline control, composition with CSS. Use for complex JS-driven animations that CSS can't handle."],
  ["What is the Fetch API and how does it differ from XMLHttpRequest?", "hard", "Fetch API provides a modern, Promise-based way to make HTTP requests. fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) }).then(res => res.json()). Differences from XHR: Promise-based (no callback nesting), simpler API (single fetch call vs open/send/onload), streams support (response.body for streaming), no built-in timeout (must use AbortController), no progress events (for downloads — use ReadableStream). Fetch returns a Response object."],
  ["What is the Beacon API used for?", "hard", "navigator.sendBeacon(url, data) sends a POST request that's guaranteed to complete even if the user navigates away or closes the page. Unlike fetch/ajax, beacons are non-blocking and queued by the browser. Use cases: analytics pings before page unload, session end logging, crash reporting, form abandonment tracking. Beacons are low-priority and may be coalesced. They don't block the unload event (unlike synchronous XHR which is deprecated)."],
  ["What is the History API and how does it enable SPA routing?", "hard", "History API manipulates the browser session history. history.pushState({ page: 1 }, '', '/page2') — adds entry without page reload. history.replaceState() — modifies current entry. popstate event fires on back/forward navigation. SPA frameworks (React Router, Vue Router) use this to simulate real navigation while keeping the page loaded. Combined with server-side fallback (catch-all route for 404), enables bookmarkable, sharable URLs in SPAs."],
  ["What is the BroadcastChannel API?", "hard", "BroadcastChannel enables cross-tab communication within the same origin. const channel = new BroadcastChannel('app_channel'); channel.postMessage({ type: 'logout' }); channel.onmessage = (e) => { /* handle message */ }. Use cases: sync state across tabs (logout, theme change, cart update), multi-tab communication, coordination between windows. Simpler alternatives: localStorage events (storage event fires on other tabs). More targeted than localStorage."],
  ["What is IndexedDB and when would you use it over localStorage?", "hard", "IndexedDB is a NoSQL client-side database with: structured data storage (objects, files, blobs), indexes for fast queries, transactions for atomicity, large storage (unlimited, vs localStorage 5-10MB), asynchronous API (non-blocking). Use over localStorage when: storing large data (>10MB), complex querying (multiple indexes, ranges), structured data (objects, not just strings), offline apps (service workers + IndexedDB), caching API responses for offline use. More complex API — use libraries like Dexie.js, idb-keyval."],
  ["What are Service Workers and what is their lifecycle?", "hard", "Service workers are JavaScript files that run in the background, intercepting network requests (fetch event) and enabling: offline support, push notifications, background sync, caching strategies. Lifecycle: 1) Registration: navigator.serviceWorker.register('/sw.js'), 2) Installation: install event (cache static assets), 3) Waiting: waits for all tabs to close or skipWaiting(), 4) Activation: activate event (clean old caches, take control). Service workers require HTTPS (for security). They don't have DOM access."],
  ["What is a Progressive Web App (PWA)?", "hard", "PWA is a web application that provides a native-app-like experience. Requirements: HTTPS, service worker (offline support, caching), Web App Manifest (manifest.json with icons, colors, display mode), responsive design, fast load performance. Features: installable to home screen, offline functionality, push notifications, background sync, full-screen mode (display: standalone), access to device APIs (camera, geolocation). PWAs bridge web and native apps with no app store required."],
  ["What is the Web App Manifest?", "hard", "manifest.json (linked via <link rel='manifest' href='/manifest.json'>) defines how the PWA behaves when installed. Properties: name (app name), short_name (icon label), description, start_url (starting page), display (fullscreen, standalone, minimal-ui, browser), icons (array of { src, sizes, type }), background_color (splash screen), theme_color (address bar), orientation (portrait/landscape). Determines what the installed app looks like."],
  ["What is the Cache API used for in service workers?", "hard", "Cache API stores Request/Response pairs for offline access. caches.open('v1').then(cache => cache.put(request, response)). Service workers use it for caching strategies: Cache First (serve from cache, fetch if miss), Network First (fetch, fallback to cache), Stale While Revalidate (serve cache, update in background), Cache Only, Network Only. The Cache API is separate from HTTP cache — controlled entirely by JS in the service worker."],
  ["What is Content Security Policy (CSP) and how do you implement it?", "hard", "CSP is a security header that prevents XSS and data injection attacks by controlling which resources can load. Implement via: <meta http-equiv='Content-Security-Policy' content='...'> or HTTP header: Content-Security-Policy: default-src 'self'. Directives: script-src (allowed JS sources), style-src, img-src, font-src, connect-src (XHR/fetch), frame-src, object-src. Nonce or hash for inline scripts: script-src 'nonce-abc123'. Report violations: report-uri /csp-report. Reduces XSS risk significantly."],
  ["What is Cross-Site Scripting (XSS) and how does HTML prevent it?", "hard", "XSS injects malicious scripts into web pages. Types: Stored (saved in DB), Reflected (in URL/request), DOM-based (client-side). HTML prevention: escape user input (replace < > & ' \"), use textContent instead of innerHTML, set Content-Security-Policy, sanitize HTML with DOMPurify, use httpOnly cookies (prevent JS access), validate/encode all outputs. React/Vue automatically escape output (unless dangerouslySetInnerHTML or v-html used). Never trust user input."],
  ["What is the difference between same-origin policy and CORS?", "hard", "Same-origin policy: browsers block cross-origin requests by default (different protocol, domain, or port). Script from https://siteA.com cannot fetch https://siteB.com/api. CORS (Cross-Origin Resource Sharing) relaxes this: server returns headers (Access-Control-Allow-Origin: https://siteA.com) to explicitly allow cross-origin requests. Preflight requests (OPTIONS method) for non-simple requests (custom headers, non-standard content types). Credentials (cookies, auth headers) require Access-Control-Allow-Credentials: true."],
  ["What are iframes security concerns (clickjacking) and sandbox attribute?", "hard", "Clickjacking: attacker embeds your page in an iframe, overlays invisible buttons, tricking users into clicking your site. Prevention: X-Frame-Options: DENY or SAMEORIGIN header. The sandbox attribute on iframes restricts capabilities: sandbox='' (all restrictions), allow-scripts (JS enabled), allow-same-origin, allow-forms, allow-popups, allow-modals, allow-presentation. Use on untrusted content. Example: <iframe sandbox='allow-scripts allow-forms' src='...'></iframe>. Always sandbox third-party iframes."],
  ["What is WebRTC and what HTML elements does it use?", "hard", "WebRTC enables real-time peer-to-peer communication (audio, video, data) in the browser. HTML elements: <video> for camera/stream display (autoplay, muted for local video), <audio> for audio calls. JS API: getUserMedia (camera/mic access), RTCPeerConnection (P2P connection), RTCDataChannel (data transfer). For signaling: WebSocket to exchange SDP/ICE candidates. Used for: video calls, screen sharing, file sharing, live streaming."],
  ["What is the Permissions API?", "hard", "Permissions API checks and requests permissions for powerful APIs. navigator.permissions.query({ name: 'geolocation' }).then(result => { if (result.state === 'granted') { ... } }). States: granted, denied, prompt (user hasn't decided). Supports: geolocation, notifications, camera, microphone, midi, clipboard-read, clipboard-write, etc. User-friendly: check permission state before requesting, handle denial gracefully. Don't request permissions proactively — wait for user action."],
  ["What are the performance best practices for loading fonts in HTML?", "hard", "1) Preload key fonts: <link rel='preload' href='font.woff2' as='font' crossorigin>. 2) Use font-display: swap (show fallback immediately, swap to custom font). 3) Self-host fonts (avoid external CDN DNS lookups). 4) Use woff2 format (best compression). 5) Subset fonts (only needed characters). 6) Use variable fonts (single file per family). 7) Use next/font (Next.js auto-optimization). 8) Set fallback font metrics to minimize layout shift (size-adjust)."],
  ["What is HTTP/2 Server Push and how does it relate to HTML resource hints?", "hard", "HTTP/2 Server Push sends resources to the client before the client requests them (proactive). The server knows that HTML needs CSS → pushes CSS with HTML response. Resource hints (preload, prefetch, preconnect) are HTTP/2 Push alternatives where the CLIENT decides to fetch. Push is server-initiated; hints are client-initiated. Push has issues (over-push waste, cache awareness), so hints are preferred now. 103 Early Hints status code further improves hint delivery."],
  ["What are Core Web Vitals (LCP, FID/INP, CLS)?", "hard", "Core Web Vitals are Google page experience metrics. LCP (Largest Contentful Paint) < 2.5s — loading performance (hero image, heading). FID (First Input Delay) < 100ms — interactivity (replaced by INP in 2024). INP (Interaction to Next Paint) < 200ms — overall responsiveness. CLS (Cumulative Layout Shift) < 0.1 — visual stability. Measured for real users (field data — CrUX) and lab (Lighthouse). Impact SEO ranking. Optimize: preload LCP image, minimize main thread blocking, set size attributes on images."],
  ["How does the browser handle JavaScript execution vs HTML parsing?", "hard", "Default: parser encounters <script>, STOPS parsing HTML, fetches script (if external), executes script (blocking), resumes HTML parsing. This ensures script can access/modify the DOM (script is synchronous). async: script fetched in parallel with parsing, executes as soon as downloaded (parsing pauses). defer: fetched in parallel, executes after parsing (in document order). Module scripts (type='module') default to deferred. The preload scanner discovers resources during parser pauses."],
  ["What is the Event Loop in the browser context?", "hard", "The event loop coordinates: Call Stack (JS execution), Microtask Queue (Promise.then, queueMicrotask, MutationObserver), Macrotask Queue (setTimeout, setInterval, I/O, UI events). Order: 1) Execute all synchronous code (call stack), 2) Process all microtasks (until empty), 3) Render (requestAnimationFrame, paint), 4) Process one macrotask, then repeat. Microtasks include: Promise callbacks, async/await continuations, queueMicrotask. Macrotasks include: setTimeout, setInterval, click events, fetch response. requestAnimationFrame runs before rendering."],
  ["What is WASM (WebAssembly) and how does it relate to HTML?", "hard", "WebAssembly is a binary instruction format for a stack-based virtual machine. Compile languages (C, C++, Rust, Go) to .wasm files that run near-native speed in browsers. Loaded via: WebAssembly.instantiate(). The <script type='module'> loads .wasm. C++ game engines, video codecs, image processing, scientific computing compile to WASM. WASM doesn't replace JS — it supplements CPU-heavy tasks. No DOM access — calls JS for DOM interaction. Portable across browsers (Chrome, Firefox, Safari, Edge)."],

  // ── Conceptual / Industry (current) ────────────────────────────────────────
  ["Why does semantic HTML matter for accessibility and SEO?", "med", "Semantic elements give meaning to content structure. Accessibility: screen readers provide navigation (jump to <nav>, read by <main>), explore landmarks, announce roles. Users can navigate by headings, lists, tables, and landmarks. SEO: search engines use semantic structure to understand content hierarchy, generate featured snippets, and rank pages. Non-semantic <div> soup provides no structure hints — both search engines and screen readers struggle."],
  ["What is the document outline and how do heading levels define it?", "med", "Document outline is the heading hierarchy of a page (like a table of contents). <h1> is the page title. <h2> are major sections. <h3> are sub-sections. Screen readers let users navigate by headings. Rules: one <h1> per page, don't skip levels (h1→h3 breaks the outline), nest logically (h1 > h2 > h3). The outline algorithm in HTML5 allows multiple h1s per sectioning element but browser support is limited — use hierarchical headings instead."],
  ["Why should you avoid skipping heading levels (h1 to h3)?", "med", "Skipping heading levels (h1 then h3) breaks the document outline for screen reader users. They navigate by heading level — jumping from h1 to h3 implies missing content. Fix: nest headings properly (h1 → h2 → h3 and back to h2). If h3 visually looks right but h2 is missing, use CSS to style a h2 as h3-level instead of using the wrong tag. Heading levels should reflect hierarchy, not visual size."],
  ["When should you use ARIA vs native HTML elements? (first rule of ARIA)", "med", "First rule of ARIA: If you can use a native HTML element that has the semantics and behavior you need, use it. Don't add ARIA to a <div> to make it a button — use <button>. Native elements have: built-in keyboard handling, browser accessibility support, focus management, and role inheritance. Use ARIA when: building custom widgets with no native equivalent (tree, combobox, slider, carousel), enhancing existing elements (aria-expanded on a button), dynamic content (aria-live)."],
  ["What is the accessibility tree and how does the browser build it?", "hard", "The accessibility tree is a subset of the DOM used by assistive technologies (screen readers). The browser builds it by: 1) Starting with the Render Tree (visible elements), 2) Mapping each element to its accessible role (implicit from HTML or explicit from ARIA), 3) Computing accessible name (from content, aria-label, aria-labelledby, or associated label), 4) Gathering accessible states (disabled, expanded, selected), 5) Pruning elements with aria-hidden='true'. The tree is flat (focus order) rather than visual layout."],
  ["What is the difference between aria-label, aria-labelledby, and aria-describedby?", "hard", "aria-label: provides a direct label string (aria-label='Close'). Overrides visible text. aria-labelledby: references one or more elements by ID to compose the accessible name (aria-labelledby='title desc'). Higher priority than aria-label. aria-describedby: provides additional description (beyond the label). Example: <button aria-label='Close' aria-describedby='tooltip'>X</button>. The label is the name (short); description is additional info (longer)."],
  ["What is aria-live and when do you use polite vs assertive?", "hard", "aria-live makes dynamic content announcements to screen readers. polite: waits for user to finish current action before announcing. assertive: interrupts current action immediately. Use polite for: chat notifications, status updates, search results, loading states (non-urgent updates). Use assertive sparingly for: critical errors, time-sensitive alerts, form validation failures. aria-live region must be present in the DOM before content changes. Alternatively use role='alert' (which is assertive)."],
  ["What is the role of landmark roles (banner, main, navigation, contentinfo)?", "med", "Landmark roles are regions that help screen reader users navigate a page. Main landmarks: role='banner' (<header>), role='navigation' (<nav>), role='main' (<main>), role='complementary' (<aside>), role='contentinfo' (<footer>), role='search' (<form role='search'>), role='form', role='region' (with aria-label). Users can jump between landmarks using keyboard shortcuts (NVDA: D, VoiceOver: rotor). Each landmark should have a unique label if multiple of same type."],
  ["How do you make a custom widget keyboard accessible?", "hard", "Requirements: 1) Focusable via tabindex='0', 2) Keyboard event handlers for: Enter/Space (activate), Arrow keys (navigation, selection), Escape (dismiss), Tab (move focus out), 3) Visible focus indicator (:focus-visible), 4) Appropriate ARIA role and states (aria-expanded, aria-selected), 5) Follow ARIA Authoring Practices Guide (APG) patterns. Example custom combobox: Enter opens list, Arrow keys navigate, Enter selects, Escape closes. Each widget type has a standard keyboard pattern — follow it."],
  ["What is the autocomplete attribute and why does it improve form UX?", "med", "autocomplete helps browsers fill form fields with saved user data. Values: 'name', 'email', 'tel', 'street-address', 'country', 'cc-number', 'current-password', 'new-password', 'one-time-code', 'username', 'organization', 'bday', etc. Benefits: faster form completion, less typing, reduced errors. For password fields: autocomplete='current-password' (login) and autocomplete='new-password' (signup/change) trigger browser's password manager. Security: 'off' may be ignored by modern browsers."],
  ["What input types provide built-in mobile keyboards (tel, email, number)?", "easy", "type='tel' → numeric keypad. type='email' → keyboard with @ and .com. type='number' → numeric keypad (may also show decimal). type='url' → keyboard with .com and / keys. type='search' → search button ('go') on keyboard. Using appropriate types improves mobile form UX — users see the right keyboard without tapping to change. Also triggers built-in validation patterns."],
  ["What is the pattern attribute for input validation?", "med", "pattern specifies a regex that the input value must match. <input pattern='[A-Za-z]{3}' title='Exactly 3 letters'>. Built-in validation prevents form submission if pattern doesn't match. Show custom error via title attribute. Use for: zip codes, phone numbers, product codes, custom formats. pattern is additive to type validation — doesn't replace required or other constraints. Always show a clear error message (setCustomValidity or title)."],
  ["What is the difference between novalidate and formnovalidate?", "med", "novalidate on <form>: disables ALL form validation when submitting. formnovalidate on <button>/<input type='submit'>: disables validation for THAT specific submit button. Use case: 'Save Draft' button vs 'Publish' button. Save draft doesn't need validation; publish does. <button formnovalidate>Save Draft</button> inside a form with validation. Without these, all submits trigger validation."],
  ["What is the fieldset and legend grouping for accessible forms?", "med", "<fieldset> groups related form controls. <legend> provides a label for the group. <fieldset><legend>Shipping Address</legend>...inputs...</fieldset>. Screen readers announce the legend when focusing any input inside the fieldset. Essential for: radio button groups (what option are we choosing?), address sections, payment info blocks, checkbox groups. Fieldsets can be nested. The legend is part of the fieldset's border by default."],
  ["What is the difference between the name and id attributes on form inputs?", "med", "name: used for form submission (key sent to server). Multiple inputs can share name (radio groups, checkbox arrays with []). Not required to be unique. id: used for label association (for attribute), CSS targeting (# selector), and JS (getElementById). Must be unique per page. An input should have both: name for submission, id for labeling. name is the server-side identifier; id is the client-side identifier."],
  ["What are custom elements and how do you define one with the CustomElementRegistry?", "hard", "Custom elements let you define new HTML tags. Define: class MyButton extends HTMLElement { constructor() { super(); } connectedCallback() { this.innerHTML = '<button>Click</button>'; } }. Register: customElements.define('my-button', MyButton). Use: <my-button></my-button>. Requirements: name must have a hyphen (my-button, not mybutton), extends HTMLElement (or HTMLButtonElement for customized built-in). Lifecycle: constructor, connectedCallback (inserted), disconnectedCallback (removed), attributeChangedCallback."],
  ["What is the difference between open and closed Shadow DOM?", "hard", "Open Shadow DOM: accessible via element.shadowRoot. External JS can access and modify shadow DOM content. Closed Shadow DOM: element.shadowRoot returns null. Only accessible inside the component. Most Web Component libraries create open mode (for testing/debugging). Closed mode is harder to test and debug. Benefits of closed: true encapsulation (can't be accessed from outside). Drawbacks: breaks testing, devtools inspection, and extensibility. Use open unless you have strict encapsulation needs."],
  ["What are lifecycle callbacks of a custom element (connectedCallback, etc.)?", "hard", "constructor(): called when element is created (before being added to DOM). Use for: initializing state, setting up shadow DOM. connectedCallback(): element added to DOM. Use for: fetching data, setting up event listeners, rendering. disconnectedCallback(): element removed from DOM. Use for: cleaning up (removing listeners, canceling timers). attributeChangedCallback(name, oldVal, newVal): observed attributes change. Use for: reacting to attribute updates. adoptedCallback(): element moved to another document. Only connectedCallback and attributeChangedCallback are commonly used."],
  ["How do slots enable content projection in web components?", "hard", "Slots in Shadow DOM project external content into component template. Default slot: <slot></slot> catches all children. Named slots: <slot name='header'></slot> corresponds to <span slot='header'> in light DOM. Multiple named slots allow complex layouts. Fallback content inside <slot> renders if no light DOM content provided. Slot content is rendered in the component context but styled from the light DOM scope. The ::slotted() pseudo-element styles slotted content from shadow CSS."],
  ["What are declarative Shadow DOM and its SSR benefits?", "hard", "Declarative Shadow DOM creates shadow roots in server-rendered HTML without JS. Syntax: <template shadowrootmode='open'> <style>...</style> <slot></slot> </template>. Benefits for SSR: content is visible before JS loads (no FOUC), works with or without JS, searchable by crawlers, compatible with streaming HTML. After HTML parsing, the shadow root is attached declaratively. Supported in Chrome 90+, Firefox 131+. Essential for SSR web components."],
  ["What is the loading='lazy' attribute and which elements support it?", "med", "loading='lazy' defers loading of offscreen images and iframes. Supported on: <img>, <iframe>. Not supported on: <video> poster, background images (use Intersection Observer). Lazy loading starts when the element approaches the viewport (browser-dependent threshold, typically ~1250px). Benefits: reduces initial page weight, saves bandwidth, faster page load. Use on: below-fold images, embedded iframes (YouTube, maps). Don't use on: above-fold/LCP images (use loading='eager' or priority)."],
  ["What is the fetchpriority attribute on images and scripts?", "hard", "fetchpriority='high' or 'low' hints the browser about resource loading priority. On <img>: fetchpriority='high' for LCP images (hero banner). On <script>: fetchpriority='low' for non-critical scripts. Works alongside loading='lazy' and preload. The browser may or may not honor the hint — it's advisory. Use for: fine-tuning resource loading beyond preload. Combining preload + fetchpriority='high' gives the strongest signal for critical resources."],
  ["What is the decoding attribute (async, sync, auto) on images?", "med", "decoding controls how the browser decodes images. async (default): decode off the main thread (non-blocking, may show placeholder briefly). sync: decode on the main thread (blocks rendering but image appears instantly). auto: browser chooses best method. Use decoding='async' for most images (better performance). Use decoding='sync' for above-fold images that should appear immediately (may hurt performance). The attribute is a hint, not a guarantee."],
  ["What are structured data and JSON-LD for SEO?", "med", "Structured data provides explicit information about page content to search engines. JSON-LD is the recommended format: <script type='application/ld+json'> { '@context': 'https://schema.org', '@type': 'Article', 'headline': '...', 'author': { '@type': 'Person', 'name': '...' } } </script>. Schema types: Article, Product, FAQPage, HowTo, Organization, LocalBusiness, Recipe, Event. Benefits: rich search results (star ratings, pricing, FAQs, breadcrumbs), knowledge panels, voice search optimization. Test with Google Rich Results Test."],
  ["What is the canonical link tag and why does it matter for SEO?", "med", "<link rel='canonical' href='https://example.com/page'> tells search engines the PREFERRED URL when duplicate content exists on multiple URLs. Reasons for duplicates: WWW vs non-WWW, HTTP vs HTTPS, URL parameters (sorting, filtering), trailing slashes, printer-friendly versions. Canonical prevents: split ranking signals, duplicate content penalties, wasted crawl budget. Always self-referencing canonical (even on the canonical URL itself). Essential for e-commerce (product in multiple categories)."],
  ["What is the difference between meta robots noindex and nofollow?", "med", "noindex: tells search engines NOT to include the page in search results. nofollow: tells search engines NOT to follow links on the page (doesn't prevent indexing). Combine: <meta name='robots' content='noindex, nofollow'>. noindex is for: thin content, admin pages, duplicate pages, pagination. nofollow was originally for untrusted links — now also used for paid links, login pages. In modern SEO, most links are discovered naturally — nofollow is less impactful."],
  ["What is the rel='noopener noreferrer' and why use it with target='_blank'?", "med", "rel='noopener' prevents the new page from accessing window.opener (prevents tabnabbing). rel='noreferrer' additionally hides the Referer header. Best practice: <a href='...' target='_blank' rel='noopener noreferrer'>. Modern browsers (Chrome 88+) treat target='_blank' as noopener by default, but noreferrer is still needed for referrer privacy. Security + privacy in one attribute pair."],
  ["What is the popover attribute (Popover API) in modern HTML?", "hard", "The Popover API provides native popover/tooltip functionality without JS. <button popovertarget='mypopover'>Toggle</button> <div id='mypopover' popover>Popover content</div>. Features: light dismiss (click outside or Escape to close), auto-positioning near trigger, top-layer rendering (above everything else, no z-index issues), focus trapping. CSS pseudo-elements: ::backdrop for overlay. popover='manual' skips light dismiss. Native alternative to libraries like Tippy.js, Popper."],
  ["What is the inert attribute and what does it do?", "hard", "inert makes an element and its subtree non-interactive: not focusable, not clickable, not accessible (screen readers skip it). <div inert>...</div>. Use cases: modals (inert background while dialog open), offscreen navigation panels, transitioning pages (prevent interaction during animation), disabled form sections. Combined with: visibility: hidden for non-interactive but visible content. Harder than pointer-events: none (doesn't trap focus). Replaces older approaches like aria-hidden + focus management."],
  ["What is the difference between the hidden attribute and CSS display:none?", "med", "hidden attribute: semantically hides the element (hidden='hidden' or just 'hidden'). Browser applies display: none by default but can be overridden: [hidden] { display: inline; } (not recommended). CSS display:none: presentational hiding only. HTML spec says hidden shouldn't be overridden for non-clip reasons. Use hidden for: logically hidden content (not yet loaded, inactive). Use CSS for: responsive hiding (show/hide at breakpoints), hover/focus-based hiding. Accessibility: both hide from screen readers."],

  // ── Code / Implementation ──────────────────────────────────────────────────
  ["Mark up an accessible login form with labels, autocomplete, and a submit button.", "med", "<form method='post' action='/login'> <label for='email'>Email:</label> <input type='email' id='email' name='email' autocomplete='email' required> <label for='password'>Password:</label> <input type='password' id='password' name='password' autocomplete='current-password' required minlength='8'> <button type='submit'>Sign In</button> </form>. Wrap in <fieldset><legend>Login</legend> for extra structure."],
  ["Mark up a semantic blog article with header, time, author, and content.", "med", "<article> <header> <h1>Blog Post Title</h1> <p>By <span itemprop='author'>John Doe</span> • <time datetime='2024-01-15'>January 15, 2024</time></p> </header> <section> <p>Article content...</p> </section> <footer> <p>Tags: <a href='/tag/css'>CSS</a>, <a href='/tag/html'>HTML</a></p> </footer> </article>."],
  ["Write the HTML for an accessible navigation menu using nav and a list.", "med", "<nav aria-label='Main navigation'> <ul> <li><a href='/' aria-current='page'>Home</a></li> <li><a href='/about'>About</a></li> <li><a href='/services'>Services</a></li> <li><a href='/contact'>Contact</a></li> </ul> </nav>. Use aria-current='page' on the active page link."],
  ["Mark up an accessible data table with caption, thead, th scope, and tbody.", "med", "<table> <caption>Monthly Sales Report 2024</caption> <thead> <tr> <th scope='col'>Month</th> <th scope='col'>Revenue</th> <th scope='col'>Expenses</th> </tr> </thead> <tbody> <tr> <th scope='row'>January</th> <td>$10,000</td> <td>$7,500</td> </tr> </tbody> <tfoot> <tr> <th scope='row'>Total</th> <td>$120,000</td> <td>$90,000</td> </tr> </tfoot> </table>. scope='col' for column headers, scope='row' for row headers."],
  ["Write HTML for a responsive image using <picture> with multiple sources.", "med", "<picture> <source media='(min-width: 1024px)' srcset='hero-desktop.webp' type='image/webp'> <source media='(min-width: 768px)' srcset='hero-tablet.webp' type='image/webp'> <source srcset='hero-mobile.webp' type='image/webp'> <img src='hero-fallback.jpg' alt='Hero banner' width='1200' height='600' loading='lazy'> </picture>. Provides WebP with JPEG fallback, different crops per breakpoint."],
  ["Write an <img> with srcset and sizes for responsive resolution switching.", "med", "<img src='photo-800.jpg' srcset='photo-400.jpg 400w, photo-800.jpg 800w, photo-1200.jpg 1200w' sizes='(max-width: 600px) 100vw, (max-width: 1024px) 50vw, 800px' alt='Description' width='800' height='600' loading='lazy'>. Browser picks best image based on viewport width and DPR."],
  ["Mark up an accessible radio button group using fieldset and legend.", "med", "<fieldset> <legend>Select shipping method</legend> <label> <input type='radio' name='shipping' value='standard' checked> Standard (5-7 days) </label> <label> <input type='radio' name='shipping' value='express'> Express (2-3 days) </label> <label> <input type='radio' name='shipping' value='overnight'> Overnight </label> </fieldset>. No for/id needed when label wraps input."],
  ["Write HTML for a native accordion using <details> and <summary>.", "easy", "<details name='faq'> <summary>How do I reset my password?</summary> <p>Go to Settings → Security → Reset Password. Follow the email instructions.</p> </details> <details name='faq'> <summary>How do I delete my account?</summary> <p>Contact support to initiate account deletion.</p> </details>. The name attribute groups accordion items — only one open at a time."],
  ["Write HTML for a modal using the native <dialog> element.", "med", "<dialog id='myModal'> <form method='dialog'> <h2>Confirm Action</h2> <p>Are you sure you want to proceed?</p> <div class='actions'> <button type='submit' value='cancel'>Cancel</button> <button type='submit' value='confirm' class='primary'>Confirm</button> </div> </form> </dialog> <button onclick='document.getElementById(\"myModal\").showModal()'>Open Modal</button>. Built-in: focus trap, Escape to close, ::backdrop styling."],
  ["Mark up an accessible search form with a labeled input and submit.", "med", "<form role='search' action='/search' method='get'> <label for='search-query' class='sr-only'>Search the site</label> <input type='search' id='search-query' name='q' placeholder='Search...' autocomplete='off'> <button type='submit' aria-label='Search'>🔍</button> </form>. role='search' is a landmark for screen readers."],
  ["Write the meta tags needed for a responsive, SEO-friendly page head.", "med", "<head> <meta charset='UTF-8'> <meta name='viewport' content='width=device-width, initial-scale=1.0'> <title>My Page Title | Site Name</title> <meta name='description' content='Brief description for SEO'> <link rel='canonical' href='https://example.com/page'> <meta name='robots' content='index, follow'> </head>."],
  ["Write Open Graph meta tags for sharing a page on social media.", "med", "<meta property='og:title' content='Page Title'> <meta property='og:description' content='Brief description'> <meta property='og:image' content='https://example.com/og-image.jpg'> <meta property='og:url' content='https://example.com/page'> <meta property='og:type' content='article'> <meta property='og:site_name' content='Site Name'> <meta name='twitter:card' content='summary_large_image'> <meta name='twitter:image' content='https://example.com/og-image.jpg'>."],
  ["Mark up a video with captions track and fallback text.", "med", "<video controls width='640' height='360' poster='thumbnail.jpg'> <source src='video.mp4' type='video/mp4'> <source src='video.webm' type='video/webm'> <track src='captions-en.vtt' kind='captions' srclang='en' label='English' default> <p>Your browser doesn't support video. <a href='video.mp4'>Download the video</a>.</p> </video>. Provide multiple formats and captions."],
  ["Write HTML for a file upload form with multipart/form-data enctype.", "med", "<form action='/upload' method='POST' enctype='multipart/form-data'> <label for='file-upload'>Choose file:</label> <input type='file' id='file-upload' name='document' accept='.pdf,.doc,.docx' multiple> <small>Accepted: PDF, DOC, DOCX — max 10MB</small> <button type='submit'>Upload</button> </form>. accept limits file types; multiple allows multi-file upload."],
  ["Mark up an accessible breadcrumb navigation with aria-current.", "med", "<nav aria-label='Breadcrumb'> <ol> <li><a href='/'>Home</a></li> <li><a href='/products'>Products</a></li> <li><a href='/products/laptops'>Laptops</a></li> <li aria-current='page'>MacBook Pro</li> </ol> </nav>. The last item should be text (not a link) with aria-current='page'."],
  ["Write a form with client-side validation using required, type, and pattern.", "med", "<form novalidate> <label for='phone'>Phone (XXX-XXX-XXXX):</label> <input type='tel' id='phone' name='phone' pattern='[0-9]{3}-[0-9]{3}-[0-9]{4}' title='Format: XXX-XXX-XXXX' required> <label for='zip'>ZIP Code:</label> <input type='text' id='zip' name='zip' pattern='[0-9]{5}' maxlength='5' required> <button type='submit'>Submit</button> </form>. Use novalidate with custom validation UI for better error messages."],
  ["Mark up a contact form with name, email, message, and proper labels.", "easy", "<form action='/contact' method='POST'> <label for='name'>Name:</label> <input type='text' id='name' name='name' required> <label for='email'>Email:</label> <input type='email' id='email' name='email' required> <label for='message'>Message:</label> <textarea id='message' name='message' rows='5' required></textarea> <button type='submit'>Send Message</button> </form>."],
  ["Write HTML to lazy-load an offscreen image natively.", "easy", "<img src='large-photo.jpg' alt='Description' width='1200' height='800' loading='lazy'>. loading='lazy' tells the browser to defer loading until near viewport. Always include width/height to prevent layout shift."],
  ["Define a basic custom element <my-counter> with a connectedCallback.", "hard", "class MyCounter extends HTMLElement { constructor() { super(); this.count = 0; } connectedCallback() { this.innerHTML = `<button id='dec'>-</button> <span id='count'>${this.count}</span> <button id='inc'>+</button>`; this.querySelector('#inc').onclick = () => this.count++; this.querySelector('#dec').onclick = () => this.count--; } get count() { return Number(this.getAttribute('count')) || 0; } set count(val) { this.setAttribute('count', val); this.querySelector('#count').textContent = val; } } customElements.define('my-counter', MyCounter);"],
  ["Write a <template> and clone it into the DOM with JavaScript.", "med", "<template id='card-template'> <div class='card'> <h3 class='title'></h3> <p class='desc'></p> </div> </template> <script> const template = document.getElementById('card-template'); const clone = document.importNode(template.content, true); clone.querySelector('.title').textContent = 'Card Title'; clone.querySelector('.desc').textContent = 'Description'; document.body.appendChild(clone); </script>."],
  ["Mark up a figure with an image and a figcaption.", "easy", "<figure> <img src='photo.jpg' alt='Sunset over mountains'> <figcaption>Sunset at Grand Canyon, Arizona — October 2024</figcaption> </figure>. <figure> associates the caption with the image semantically."],
  ["Write HTML for a skip-to-content link for keyboard users.", "med", "<a href='#main-content' class='skip-link'>Skip to main content</a> <main id='main-content'> <h1>Page Content</h1> ... </main>. CSS: .skip-link { position: absolute; left: -9999px; } .skip-link:focus { position: static; left: 0; }. The link appears when focused (tab) and disappears otherwise."],
  ["Mark up a star rating widget accessibly with radio inputs.", "hard", "<fieldset> <legend>Rate this product</legend> <div class='star-rating'> <input type='radio' id='star5' name='rating' value='5'> <label for='star5' aria-label='5 stars'>★</label> <input type='radio' id='star4' name='rating' value='4'> <label for='star4' aria-label='4 stars'>★</label> <input type='radio' id='star3' name='rating' value='3' checked> <label for='star3' aria-label='3 stars'>★</label> <input type='radio' id='star2' name='rating' value='2'> <label for='star2' aria-label='2 stars'>★</label> <input type='radio' id='star1' name='rating' value='1'> <label for='star1' aria-label='1 star'>★</label> </div> </fieldset>. CSS hides native radio, styles labels as stars."],
  ["Write a select dropdown with optgroup grouping.", "easy", "<label for='car'>Select a car:</label> <select id='car'> <optgroup label='German'> <option value='audi'>Audi</option> <option value='bmw'>BMW</option> <option value='mercedes'>Mercedes</option> </optgroup> <optgroup label='Japanese'> <option value='toyota'>Toyota</option> <option value='honda'>Honda</option> <option value='nissan'>Nissan</option> </optgroup> </select>."],
  ["Mark up an address using the <address> element semantically.", "easy", "<address> <strong>Company Name</strong><br> 123 Main Street<br> Suite 400<br> San Francisco, CA 94102<br> <a href='mailto:info@example.com'>info@example.com</a><br> <a href='tel:+14155550123'>(415) 555-0123</a> </address>. <address> is for contact info only, not all addresses."],
  ["Write HTML for an accessible toggle switch using a checkbox and ARIA.", "hard", "<label class='toggle-switch'> <input type='checkbox' role='switch' aria-checked='false' id='notifications'> <span class='slider'></span> Notifications </label>. CSS styles the checkbox as a switch. role='switch' announces as 'toggle switch' to screen readers. JS: input.addEventListener('change', () => input.setAttribute('aria-checked', input.checked))."],
  ["Add JSON-LD structured data for an Article to a page.", "med", "<script type='application/ld+json'> { '@context': 'https://schema.org', '@type': 'Article', 'headline': 'Article Title', 'description': 'Brief description', 'author': { '@type': 'Person', 'name': 'John Author' }, 'datePublished': '2024-01-15', 'dateModified': '2024-01-20', 'image': 'https://example.com/hero.jpg', 'publisher': { '@type': 'Organization', 'name': 'Publisher Name' } } </script>."],
  ["Write a progress bar using the <progress> element.", "easy", "<label for='upload-progress'>Upload progress:</label> <progress id='upload-progress' value='70' max='100'>70%</progress>. For indeterminate: <progress> (no value). <progress> is for determinate tasks; <meter> for scalar measurements (disk usage)."],
  ["Mark up a pricing table accessibly with proper headers.", "med", "<table> <caption>Pricing Plans</caption> <thead> <tr> <th scope='col'>Feature</th> <th scope='col' id='basic'>Basic</th> <th scope='col' id='pro'>Pro</th> </tr> </thead> <tbody> <tr> <th scope='row'>Users</th> <td headers='basic'>1</td> <td headers='pro'>Unlimited</td> </tr> </tbody> </table>. headers attribute associates cells with multiple column headers."],
  ["Write resource hints (preconnect, preload) for a web font.", "med", "<link rel='preconnect' href='https://fonts.googleapis.com'> <link rel='preconnect' href='https://fonts.gstatic.com' crossorigin> <link rel='preload' href='/fonts/custom-font.woff2' as='font' type='font/woff2' crossorigin>. preconnect resolves DNS+TCP+TLS early. preload starts font download early."],
  ["Write an anchor that downloads a file with a custom filename.", "easy", "<a href='/reports/q4-2024.pdf' download='Q4-2024-Report.pdf'>Download Q4 Report</a>. The download attribute overrides the server filename. Only works for same-origin URLs and blob URLs."],
  ["Mark up a multi-step form section with fieldsets and legends.", "med", "<form> <fieldset> <legend>Step 1: Personal Info</legend> ... </fieldset> <fieldset> <legend>Step 2: Address</legend> ... </fieldset> <fieldset> <legend>Step 3: Payment</legend> ... </fieldset> <button type='submit'>Submit</button> </form>. Use JS/CSS to show one fieldset at a time for multi-step UX."],
  ["Write a responsive iframe embed for a YouTube video.", "med", "<div class='video-wrapper' style='position: relative; padding-bottom: 56.25%; height: 0;'> <iframe src='https://www.youtube.com/embed/VIDEO_ID' title='YouTube video player' style='position: absolute; top: 0; left: 0; width: 100%; height: 100%;' allow='accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture' allowfullscreen loading='lazy'> </iframe> </div>. 56.25% = 16:9 aspect ratio."],
  ["Add a favicon and apple-touch-icon to the document head.", "easy", "<link rel='icon' type='image/svg+xml' href='/favicon.svg'> <link rel='alternate icon' href='/favicon.ico'> <link rel='apple-touch-icon' sizes='180x180' href='/apple-touch-icon.png'>. SVG is preferred for modern browsers; .ico for fallback."],
  ["Write the manifest link and theme-color meta for a PWA.", "med", "<link rel='manifest' href='/manifest.json'> <meta name='theme-color' content='#007bff' media='(prefers-color-scheme: light)'> <meta name='theme-color' content='#1a1a2e' media='(prefers-color-scheme: dark)'>. theme-color can be light/dark aware. manifest.json defines the PWA install experience."],

  // ── Tricky output / behavior ───────────────────────────────────────────────
  [`<p><div>text</div></p> — is this valid? What does the browser do?`, "hard", "No — <p> cannot contain <div> (p is a phrasing content element, div is flow content). The browser auto-closes <p> before <div>: <p></p><div>text</div><p></p>. Two empty paragraphs with a div between. Always check: only phrasing/inline elements inside <p>. This is a common HTML validation error."],
  [`<a href='#'><div>...</div></a> — is wrapping a block in an anchor valid in HTML5?`, "med", "Yes, HTML5 allows <a> to contain flow content (block elements). Previously invalid in HTML4. Now you can wrap entire sections: <a href='/page'> <div> <h2>Title</h2> <p>Description</p> </div> </a>. Keep the link accessible — ensure descriptive text or aria-label inside."],
  [`Two elements share id='x'. What does getElementById return and is it valid?`, "med", "getElementById returns the FIRST element in DOM order with that id. It's INVALID HTML — ids must be unique per page. Duplicate ids cause: CSS targeting issues (only first styled), accessibility problems (for/id association may break, only first found), JavaScript bugs (only first returned). Always validate HTML to catch duplicate ids."],
  [`<button>Click</button> inside a <form> with no type — does it submit? Why?`, "med", "Yes — <button> inside a <form> defaults to type='submit'. Clicking it submits the form. To prevent submission: always set type='button' for non-submit buttons: <button type='button'>Click</button>. Or use <input type='button'> which doesn't submit by default."],
  [`<input> outside a <form> but with form='id' attribute — does it submit with that form?`, "hard", "Yes — the form attribute associates an input with a form by id, even if not nested inside it. <form id='myForm'>...</form> <input name='extra' form='myForm'>. This enables form inputs to be placed anywhere in the DOM. Primarily used for: inputs inside complex layouts (tables, grids) that can't nest in a form."],
  [`<label>Email <input></label> — is the input associated without a for attribute?`, "med", "Yes — wrapping the input inside the label implicitly associates them. Clicking the label focuses the input. It's equivalent to: <label for='email'>Email</label> <input id='email'>. Both approaches are valid. Wrapping is simpler; explicit for/id is more flexible (label can be placed away from input)."],
  [`<img src='x.jpg'> with no alt — how do screen readers treat it?`, "med", "Screen readers may: read the filename ('x.jpg'), announce 'image' (no description), or say 'unlabeled image'. The result varies by screen reader. If the image is decorative: use alt='' (empty). If informative: provide meaningful alt text. No alt attribute = poor accessibility. Some screen readers also read the title attribute if present, but alt is the primary source."],
  [`<table><tr><td>...</td></tr></table> with no tbody — what does the browser insert?`, "med", "The browser IMPLICITLY inserts <tbody> around the <tr>. The DOM ends up as: <table><tbody><tr><td>...</td></tr></tbody></table>. This is because <tbody> is a required element per HTML spec (implied). Similarly for <thead> and <tfoot>. Always use explicit <thead>, <tbody>, <tfoot> for clarity and CSS targeting."],
  [`Self-closing <div /> in HTML (not XHTML) — how is it parsed?`, "hard", "HTML (not XHTML) ignores the self-closing slash. <div /> is parsed as <div> (opening tag with no closing). Everything after is a child of that div until a </div> or another closing div is found. The slash is treated as an empty attribute. XHTML requires <div /> syntax. HTML5: void elements only are self-closing (img, br, hr, input, meta, link)."],
  [`<script defer> in <body> vs <head> — does defer change anything in body?`, "hard", "defer works as intended in both <head> and <body>. The script is fetched in parallel and executes after HTML parsing completes. However, putting defer scripts in <body> is unusual — the spec expects defer in <head>. Browsers may differ. Best practice: use defer in <head> for all scripts that need DOM readiness."],
  [`async vs defer on two scripts — which guarantees execution order?`, "hard", "defer guarantees execution order (document order) after parsing. async does NOT guarantee order — whichever script downloads first executes first. Use defer when: scripts have dependencies on each other (jQuery before plugins), or order matters. Use async for: independent scripts (analytics, ads) where order doesn't matter."],
  [`<ul><div>item</div></ul> — is a div a valid child of ul? What happens?`, "med", "No — <ul> children must be <li> only (or script elements). The browser will auto-close the <ul> BEFORE the <div>, treating the div as outside the list. Result: <ul></ul><div>item</div>. Only <li> elements are valid direct children of <ul> and <ol>. Same applies to <dl> (only <dt> and <dd>)."],
  [`Whitespace between inline-block elements — does HTML source spacing render?`, "med", "Yes — whitespace (newlines, spaces) between inline-block elements in HTML renders as a ~4px gap. Fixes: 1) Remove whitespace from HTML, 2) font-size: 0 on parent (set on children), 3) float instead, 4) use flexbox (no whitespace gap issue), 5) HTML comments to separate elements."],
  [`<input type='number'> — does it accept the letter 'e'? Why?`, "hard", "Yes, 'e' is accepted because 'e' is part of scientific notation (1e5 = 100000). Browsers allow 'e', 'E', '+', and '-' in number inputs to support exponents. This confuses users who expect only digits. For pure digits (e.g., credit card, PIN), use inputmode='numeric' pattern='[0-9]*' or type='tel'. Numbers are validated on form submission, not during input."],
  [`Duplicate name on radio inputs vs checkbox inputs — what behavior differs?`, "med", "Radio buttons: same name creates a group — only ONE can be selected at a time. Clicking one deselects others. Checkboxes: same name groups them for form submission (array), but MULTIPLE can be selected independently. Use name='option[]' for checkboxes to submit as array on server."],
  [`<a> with both href and a click handler that preventDefault — does navigation occur?`, "med", "If preventDefault() is called, navigation does NOT occur. But without preventDefault(), the href navigation proceeds. Common pattern: <a href='/page' onclick='event.preventDefault(); // custom behavior'>. If JS fails, the href provides fallback navigation (progressive enhancement). Always provide a meaningful href for accessibility (keyboard users expect href)."],
  [`tabindex='0' vs tabindex='5' vs tabindex='-1' — what is the tab order behavior?`, "hard", "tabindex='0': element is focusable via Tab, follows natural DOM order. tabindex='5' (positive): element is focusable, placed BEFORE all tabindex='0' elements (positive values in ascending order, then natural order after all positive). tabindex='-1': programmatically focusable only (via element.focus()), NOT in tab order. Avoid positive tabindex — breaks expected navigation flow. Use DOM order + tabindex='0' for custom interactive elements."],
  [`<details> without open attribute — is the content in the DOM and searchable?`, "med", "Yes — the content is in the DOM and fully searchable/findable. The closed <details> just HIDES the content visually — it's still parsed, indexed by search engines, and accessible via find-in-page (Ctrl+F). Screen readers can access the content (it's not display: none). Only the summary is visible; the rest is collapsed."],
  [`autofocus on two inputs — which one receives focus on load?`, "med", "Only the FIRST autofocus element in DOM order receives focus. The browser processes autofocus on the first element found and ignores subsequent ones. Having multiple autofocus elements is invalid but the behavior is defined: first wins. Best practice: only ONE autofocus per page (usually the primary input on a form)."],
  [`<meta charset> placed after 1KB of content — is the encoding still applied?`, "hard", "The <meta charset> must be within the first 1024 bytes of the document for the browser to honor it. If placed later, the browser may have already started parsing with a default encoding (usually Windows-1252 or UTF-8 depending on server header). Always place <meta charset='UTF-8'> as the first element in <head> (ideally the very first thing after <head>)."],
  [`Nested <a> tags (anchor inside anchor) — how does the parser handle it?`, "hard", "HTML parser treats nested <a> as invalid. The first <a> is closed when the second <a> is encountered. Browsers's parse error recovery closes the outer anchor. Result: <a href='1'>outer</a><a href='2'>inner</a>. Never nest anchors. Use separate elements or JS navigation on a single element."],
  [`<form> inside a <table> incorrectly — how does the parser reposition it?`, "hard", "Forms cannot be direct children of <table> or <tr>. The parser auto-closes the form before the table: <form> is moved outside the table, or the table is closed before the form, depending on spec. Solution: use <td><form>...</form></td> (form inside a table cell). Or wrap the form around the entire table (form contains table, not table contains form)."],
  [`Boolean attribute disabled='false' — is the element actually enabled?`, "med", "NO — the element is disabled! Boolean attributes are true by their presence alone. disabled='false', disabled='true', and disabled='' all disable the element. The value is ignored. To enable: remove the attribute entirely: element.removeAttribute('disabled') or element.disabled = false. This is a common HTML misconception — the attribute presence matters, not its value."],
  [`<input type='submit' value='Go'> — what text appears on the button?`, "easy", "'Go' — the value attribute sets the button's label text. Without value, default is 'Submit' (or browser-localized equivalent)."],
  [`innerHTML with a <script> tag injected — does the script execute? Why or why not?`, "hard", "No — scripts inserted via innerHTML are NOT executed. The HTML spec explicitly prevents script execution when inserted via innerHTML (security measure against XSS). Scripts created via innerHTML are parsed but not executed. To dynamically load scripts: use document.createElement('script') + appendChild, or use document.write() (rarely recommended)."],
  [`<p>Hello <p>World — how many paragraph elements does the browser create?`, "med", "Two. The browser auto-closes the first <p> before the second <p> starts. Paragraphs cannot contain other paragraphs. Result: <p>Hello</p><p>World</p>. Same for heading-to-paragraph: <h1>Title <p>text</p></h1> → <h1>Title</h1><p>text</p>."],
  [`Uppercase <DIV> in HTML5 — is it valid and how is the tag name normalized?`, "easy", "Yes — HTML is case-insensitive. <DIV>, <Div>, <div>, <DIV> are all valid. The browser normalizes tag names to lowercase in the DOM (element.tagName returns 'DIV' in uppercase, but the tree treats all as the same element). HTML5 syntax can be uppercase, lowercase, or mixed (XHTML requires lowercase)."],
  [`Missing closing </li> tags in a list — does the browser still render items?`, "easy", "Yes — <li> closing tags are optional in HTML. The browser auto-closes <li> when it encounters the next <li> or </ul>/</ol>. Similarly: <td>, <th>, <tr>, <p>, <dt>, <dd> have optional closing tags. Browser correctness varies — always write explicit closing tags for clarity."],
  [`<a href='mailto:x@y.com'> — what happens on click and is it valid HTML?`, "easy", "Clicking opens the user's default email client with the To field pre-filled. It's valid HTML. Additional params: ?subject=Hello&body=Message text. Issues: may not work on mobile without email client configured, can be used for spam harvesting. Use with caution — consider contact forms instead for anti-spam."],
  [`contenteditable div — is its content submitted with a surrounding form?`, "hard", "No — contenteditable elements are NOT form controls; their content is not submitted. The server won't receive the edited content. To submit: copy content to a hidden input on form submit (via JS), or use a form control (textarea) hidden beneath the contenteditable div."],
  [`<option selected> with multiple selected in a single-select — which is chosen?`, "med", "The FIRST selected option in DOM order is chosen. Duplicate 'selected' in a single-select is invalid HTML but browsers use the first one. For <select multiple>, multiple selected attributes work (multi-select). Always ensure only one 'selected' in single-select <select>."],
  [`role='button' on a div — is it keyboard operable by default? What is missing?`, "hard", "No — a div with role='button' is NOT keyboard operable by default. Missing: tabindex='0' (to be focusable), Enter/Space key handlers (to activate), visible focus indicator. Native <button> provides all of these automatically. Role does NOT add behavior — only semantics. You must implement keyboard handling, focus management, and ARIA states yourself. This is why the first rule of ARIA is to use native HTML elements."],
  [`aria-hidden='true' on a focusable button — what accessibility bug results?`, "hard", "The button (if already focusable) can still receive keyboard focus, but screen readers won't announce it (aria-hidden hides it from the accessibility tree). The user can tab to it but hears nothing — confusing and inaccessible. NEVER use aria-hidden on focusable elements. If you need to hide a focusable element, use disabled attribute or remove it from the DOM."],
  [`<img> with width/height attributes vs CSS — how does it affect layout shift (CLS)?`, "med", "width/height attributes (or CSS) set the image's ASPECT RATIO. The browser reserves space before the image loads, preventing layout shift. Without dimensions: the image loads at 0×0, then expands when loaded (causing CLS). Modern: <img width='800' height='600'> + CSS max-width: 100%; height: auto; — uses aspect-ratio attribute automatically. Always set width/height on images for CLS prevention."],
  [`<input required> with display:none — does form validation still block submit?`, "hard", "Yes, but the browser may not show validation errors because the element is hidden. The form will not submit, and the user sees nothing — broken UX. Never hide required form controls. Use <input type='hidden'> for non-visible required values (pre-set from server). If you must hide a visible input, use position: absolute + clip pattern, not display: none."],
];
